function parse(c){const m=c.match(/rgba?\(([^)]+)\)/);if(!m)return null;const p=m[1].split(/[ ,\/]+/).filter(Boolean).map(Number);return {r:p[0],g:p[1],b:p[2],a:p.length>3?p[3]:1};}
function lum(c){const f=v=>{v/=255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4)};return 0.2126*f(c.r)+0.7152*f(c.g)+0.0722*f(c.b);}
function bg(el){let layers=[];while(el&&el.nodeType===1){const s=getComputedStyle(el);const c=parse(s.backgroundColor);if(c&&c.a>0){layers.push(c);if(c.a>=1)break;} if(s.backgroundImage!=='none') layers.push({img:s.backgroundImage}); el=el.parentElement;}return layers;}
function blend(layers){let base={r:255,g:255,b:255};for(let i=layers.length-1;i>=0;i--){const l=layers[i];if(l.img)continue;base={r:l.r*l.a+base.r*(1-l.a),g:l.g*l.a+base.g*(1-l.a),b:l.b*l.a+base.b*(1-l.a)};}return base;}
const out=[];const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let n;
while(n=walker.nextNode()){if(!n.textContent.trim())continue;const el=n.parentElement;const r=el.getBoundingClientRect();if(r.width===0||r.height===0)continue;const s=getComputedStyle(el);if(s.visibility==='hidden'||s.display==='none')continue;
let hidden=false;for(let a=el;a;a=a.parentElement){const cs=getComputedStyle(a);if(cs.display==='none'||cs.visibility==='hidden'||parseFloat(cs.opacity)===0){hidden=true;break}}if(hidden)continue;
const fg=parse(s.color);const layers=bg(el);const b=blend(layers);const fgb={r:fg.r*fg.a+b.r*(1-fg.a),g:fg.g*fg.a+b.g*(1-fg.a),b:fg.b*fg.a+b.b*(1-fg.a)};const L1=lum(fgb),L2=lum(b);const ratio=(Math.max(L1,L2)+0.05)/(Math.min(L1,L2)+0.05);
out.push([n.textContent.trim().slice(0,40),el.tagName+'.'+el.className,s.color,JSON.stringify(b).slice(0,40),ratio.toFixed(2),s.fontSize,s.fontWeight,layers.some(l=>l.img)?'IMG':'' ,Math.round(r.x)+','+Math.round(r.y)+','+Math.round(r.width)+'x'+Math.round(r.height)].join(' | '));}
return out.join('\n');}"}

